<template>
  <div class="page-heading"><div><h1 class="page-title">推广数据日统计</h1><p>录入和查看推广账户每日运营数据；归档后的数据不会再被自动同步覆盖。</p></div><div class="daily-actions"><el-select v-model="query.accountKey" clearable placeholder="全部推广账户" class="account-picker"><el-option v-for="a in accountOptions" :key="a.key" :label="a.label" :value="a.key" /></el-select><el-date-picker v-model="dateRange" class="day-range-picker" type="daterange" value-format="YYYY-MM-DD" range-separator="至" start-placeholder="开始日期" end-placeholder="结束日期" /><PromotionDateShortcuts mode="day" :model-value="dateRange" @select="selectQuickRange" /><el-button type="primary" :loading="loading" @click="load">查询</el-button><div class="table-actions"><el-button @click="syncVisible = true">手动同步</el-button><el-button type="primary" @click="openMetric()">录入日统计</el-button></div></div></div>
  <div class="content-panel"><p class="mobile-scroll-hint">左右滑动查看完整日统计</p>
    <el-table :data="rows" v-loading="loading" border show-summary :summary-method="summary" class="metric-table" :default-sort="{ prop: 'statDate', order: 'descending' }"><el-table-column prop="statDate" label="日期" class-name="date-cell" min-width="100" /><el-table-column label="账户" min-width="66"><template #default="{ row }">{{ row.account.name }}</template></el-table-column><template v-for="field in orderedFields" :key="field.id"><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'spend'" prop="spend" :label="fieldLabel('spend', '消费')"><template #default="{ row }">{{ money(row.spend) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'impressions'" prop="impressions" :label="fieldLabel('impressions', '展现')" /><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'clicks'" prop="clicks" :label="fieldLabel('clicks', '点击')" /><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'clickRate'" :label="fieldLabel('clickRate', '点击率')"><template #default="{ row }">{{ rate(row.calculated.clickRate) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'leads'" prop="leads" :label="fieldLabel('leads', '总表单')" /><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'validLeads'" prop="validLeads" :label="fieldLabel('validLeads', '有效表单')" /><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'validRate'" :label="fieldLabel('validRate', '有效率')"><template #default="{ row }">{{ rate(row.calculated.validRate) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'averageCost'" :label="fieldLabel('averageCost', '平均成本')"><template #default="{ row }">{{ number(row.calculated.averageCost) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'validCost'" :label="fieldLabel('validCost', '有效成本')"><template #default="{ row }">{{ number(row.calculated.validCost) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'appointments'" prop="appointments" :label="fieldLabel('appointments', '到院')" /><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'transactions'" prop="transactions" :label="fieldLabel('transactions', '成交')" /><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'conversionRate'" :label="fieldLabel('conversionRate', '成交率')"><template #default="{ row }">{{ rate(row.calculated.conversionRate) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'arrivalRate'" :label="fieldLabel('arrivalRate', '到诊率')"><template #default="{ row }">{{ rate(row.calculated.arrivalRate) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'validArrivalRate'" :label="fieldLabel('validArrivalRate', '有效到诊率')"><template #default="{ row }">{{ rate(row.calculated.validArrivalRate) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'arrivalCost'" :label="fieldLabel('arrivalCost', '到院成本')"><template #default="{ row }">{{ number(row.calculated.arrivalCost) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'revenue'" prop="revenue" :label="fieldLabel('revenue', '实收')"><template #default="{ row }">{{ money(row.revenue) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.key === 'roi'" :label="fieldLabel('roi', '投产比')"><template #default="{ row }">{{ number(row.calculated.roi) }}</template></el-table-column><el-table-column :min-width="fieldMinWidth(field)" v-if="field.source === 'CUSTOM'" :key="field.id" :label="field.label"><template #default="{ row }">{{ customMetricDisplay(row.leads, row.customMetrics, field, fields) }}</template></el-table-column></template><el-table-column label="操作" width="104" class-name="operation-cell"><template #default="{ row }"><template v-if="row.details.length > 1"><el-button link type="primary" @click="openDetails(row)">查看户号</el-button></template><template v-else-if="!isArchivedReadOnly(row.details[0])"><el-button link type="primary" @click="openMetric(row.details[0])">编辑</el-button><el-button link :type="row.details[0].isArchived ? 'success' : 'warning'" :title="row.isArchived ? '点击取消归档' : '点击归档并停止自动同步覆盖'" @click="toggleArchive(row.details[0])">{{ row.isArchived ? '已归档' : '归档' }}</el-button><el-button v-if="isSuperAdmin" link type="danger" @click="removeMetric(row.details[0])">删除</el-button></template><el-tag v-else type="info" size="small" title="已归档数据仅超级管理员可修改">已归档·只读</el-tag></template></el-table-column></el-table>
  </div>
  <el-dialog v-model="detailsVisible" title="户号明细" width="min(760px, 96vw)"><el-table :data="detailRows" border class="detail-table"><el-table-column label="户号" min-width="150"><template #default="{ row }">{{ row.account.accountNo || "未填写" }}</template></el-table-column><el-table-column label="账户" prop="account.name" /><el-table-column label="消费" prop="spend" /><el-table-column label="总表单" prop="leads" /><el-table-column label="有效表单" prop="validLeads" /><el-table-column label="操作" width="190"><template #default="{ row }"><div class="detail-operation-actions"><el-button v-if="!isArchivedReadOnly(row)" link type="primary" @click="detailsVisible = false; openMetric(row)">编辑</el-button><el-button v-if="!isArchivedReadOnly(row)" link :type="row.isArchived ? 'success' : 'warning'" @click="toggleArchive(row)">{{ row.isArchived ? "已归档" : "归档" }}</el-button><el-button v-if="isSuperAdmin" link type="danger" @click="removeMetric(row)">删除</el-button><el-tag v-if="isArchivedReadOnly(row)" size="small">已归档·只读</el-tag></div></template></el-table-column></el-table></el-dialog>
  <el-dialog v-model="metricVisible" :title="metricForm.id ? '编辑日统计' : '录入日统计'" width="760px"><el-form :model="metricForm" label-width="90px" class="metric-form"><el-form-item label="推广账户" required><el-select v-model="metricForm.accountId" filterable style="width:100%"><el-option v-for="a in activeAccounts" :key="a.id" :label="`${a.project} · ${a.platform} · ${a.name} · ${a.accountNo || '无户号'}`" :value="a.id" /></el-select></el-form-item><el-form-item label="日期" required><el-date-picker v-model="metricForm.statDate" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-row :gutter="16"><el-col v-for="field in inputFields" v-show="isVisible(field.key)" :key="field.key" :span="8"><el-form-item :label="fieldLabel(field.key, field.label)"><el-input-number v-model="metricForm[field.key]" :min="0" :precision="field.money ? 2 : 0" controls-position="right" style="width:100%" /></el-form-item></el-col><el-col v-for="field in customVisibleFields.filter((item) => item.label.trim() !== '咨询留资率')" :key="field.id" :span="8"><el-form-item :label="field.label"><el-input-number v-if="field.dataType === 'NUMBER'" v-model="customValues[field.key]" :min="0" controls-position="right" style="width:100%" /><el-input v-else v-model="customValues[field.key]" /></el-form-item></el-col></el-row><el-form-item label="备注"><el-input v-model="metricForm.remark" type="textarea" :rows="2" /></el-form-item></el-form><template #footer><el-button @click="metricVisible = false">取消</el-button><el-button type="primary" :loading="saving" @click="saveMetric">保存</el-button></template></el-dialog>
  <el-dialog v-model="accountsVisible" title="推广账户" width="820px"><div class="account-actions"><el-button type="primary" @click="openAccount()">添加账户</el-button></div><el-table :data="accounts" border><el-table-column prop="project" label="项目" width="90" /><el-table-column prop="platform" label="渠道" width="120" /><el-table-column prop="name" label="账户名称" /><el-table-column prop="accountNo" label="账号 ID" /><el-table-column label="状态" width="90"><template #default="{ row }"><el-tag :type="row.status === 'ACTIVE' ? 'success' : 'info'">{{ row.status === 'ACTIVE' ? '启用' : '停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="130"><template #default="{ row }"><el-button link type="primary" @click="openAccount(row)">编辑</el-button><el-button v-if="isSuperAdmin" link type="danger" @click="removeAccount(row)">删除</el-button></template></el-table-column></el-table></el-dialog>
  <el-dialog v-model="accountVisible" :title="accountForm.id ? '编辑推广账户' : '添加推广账户'" width="520px"><el-form :model="accountForm" label-width="90px"><el-form-item label="项目" required><el-radio-group v-model="accountForm.project"><el-radio value="重庆">重庆</el-radio><el-radio value="绵阳">绵阳</el-radio></el-radio-group></el-form-item><el-form-item label="渠道" required><el-input v-model="accountForm.platform" placeholder="如：腾讯广告、巨量引擎、本地推" /></el-form-item><el-form-item label="账户名称" required><el-input v-model="accountForm.name" /></el-form-item><el-form-item label="账号 ID"><el-input v-model="accountForm.accountNo" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="accountForm.status"><el-radio value="ACTIVE">启用</el-radio><el-radio value="DISABLED">停用</el-radio></el-radio-group></el-form-item><el-form-item label="备注"><el-input v-model="accountForm.remark" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="accountVisible = false">取消</el-button><el-button type="primary" @click="saveAccount">保存</el-button></template></el-dialog>
  <el-dialog v-model="syncVisible" title="手动同步平台日统计" width="520px"><el-form :model="syncForm" label-width="90px"><el-form-item label="同步日期" required><el-date-picker v-model="syncForm.statDate" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="平台"><el-radio-group v-model="syncForm.provider"><el-radio value="">全部已启用平台</el-radio><el-radio value="TENCENT_ADS">腾讯营销</el-radio><el-radio value="OCEANENGINE">巨量引擎</el-radio></el-radio-group></el-form-item><el-form-item label="推广账户"><el-select v-model="syncForm.accountIds" multiple collapse-tags clearable placeholder="不选则同步该平台全部启用账户" style="width:100%"><el-option v-for="item in accounts" :key="item.id" :label="`${item.project} · ${item.platform} · ${item.name} · ${item.accountNo || '无户号'}`" :value="item.id" /></el-select></el-form-item></el-form><template #footer><el-button @click="syncVisible=false">取消</el-button><el-button type="primary" :loading="syncing" @click="syncData">开始同步</el-button></template></el-dialog>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import PromotionDateShortcuts from '../components/PromotionDateShortcuts.vue';
import { aggregatePromotionRows, customMetricDisplay, promotionAccountKey, type PromotionAggregateRow } from '../utils/promotionMetrics';
import { archivePromotionDailyMetric, createPromotionAccount, createPromotionDailyMetric, deletePromotionAccount, deletePromotionDailyMetric, getPromotionAccounts, getPromotionDailyMetrics, getPromotionMetricFields, syncPromotionDailyMetrics, type PromotionAccountItem, type PromotionDailyMetricItem, type PromotionMetricFieldItem, updatePromotionAccount, updatePromotionDailyMetric } from '../api/admin';
import { useAuthStore } from '../stores/auth';
const localDate = (offsetDays = 0) => { const date = new Date(); date.setDate(date.getDate() + offsetDays); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; };
const accounts = ref<PromotionAccountItem[]>([]); const fields = ref<PromotionMetricFieldItem[]>([]); const sourceRows = ref<PromotionDailyMetricItem[]>([]); const rows = computed(() => aggregatePromotionRows(sourceRows.value, fields.value)); const accountOptions = computed(() => [...new Map(accounts.value.map((account) => [promotionAccountKey(account), account])).entries()].map(([key, account]) => ({ key, label: `${account.project} · ${account.platform} · ${account.name}` }))); const loading = ref(false); const saving = ref(false); const yesterday = localDate(-1); const dateRange = ref<string[]>([yesterday, yesterday]); const query = reactive({ accountKey: '' }); const metricVisible = ref(false); const accountsVisible = ref(false); const accountVisible = ref(false);
const authStore = useAuthStore(); const isSuperAdmin = computed(() => authStore.user?.role === 'SUPER_ADMIN'); const isArchivedReadOnly = (row: PromotionDailyMetricItem) => row.isArchived && !isSuperAdmin.value;
const detailsVisible = ref(false); const detailRows = ref<PromotionDailyMetricItem[]>([]); function openDetails(row: PromotionAggregateRow) { detailRows.value = row.details; detailsVisible.value = true; }
const syncVisible = ref(false); const syncing = ref(false); const syncForm = reactive({ statDate: yesterday, provider: '' as '' | 'TENCENT_ADS' | 'OCEANENGINE', accountIds: [] as string[] });
const inputFields = [{ key: 'spend', label: '消费', money: true }, { key: 'impressions', label: '展现', money: false }, { key: 'clicks', label: '点击', money: false }, { key: 'leads', label: '总表单', money: false }, { key: 'validLeads', label: '有效表单', money: false }, { key: 'appointments', label: '到院', money: false }, { key: 'transactions', label: '成交', money: false }, { key: 'revenue', label: '实收', money: true }] as const;
const blankMetric = () => ({ id: '', accountId: '', statDate: yesterday, spend: 0, impressions: 0, clicks: 0, leads: 0, validLeads: 0, appointments: 0, transactions: 0, revenue: 0, remark: '' }); const metricForm = reactive(blankMetric()); const customValues = reactive<Record<string, string | number>>({}); const accountForm = reactive({ id: '', project: '重庆' as '重庆' | '绵阳', platform: '', name: '', accountNo: '', status: 'ACTIVE' as 'ACTIVE' | 'DISABLED', remark: '' });
const activeAccounts = computed(() => accounts.value.filter((item) => item.status === 'ACTIVE' || item.id === metricForm.accountId)); const customVisibleFields = computed(() => fields.value.filter((field) => field.source === 'CUSTOM' && field.isVisible)); const orderedFields = computed(() => fields.value.filter((field) => field.isVisible).sort((a,b) => a.sort - b.sort || a.key.localeCompare(b.key))); const rate = (value: number | null) => value === null || !Number.isFinite(value) ? '—' : `${(value * 100).toFixed(0)}%`; const number = (value: number | null) => value === null || !Number.isFinite(value) ? '—' : value.toFixed(2); const money = (value: number | null) => value === null || !Number.isFinite(value) ? '—' : Number(value.toFixed(2)).toString(); const isVisible = (key: string) => fields.value.find((field) => field.key === key)?.isVisible !== false; const fieldLabel = (key: string, fallback: string) => fields.value.find((field) => field.key === key)?.label || fallback;
const fieldMinWidth = (field: PromotionMetricFieldItem) => {
  if (['spend', 'averageCost', 'validCost', 'arrivalCost', 'revenue', 'roi'].includes(field.key)) return 58;
  if (field.key.endsWith('Rate') || field.label.endsWith('率')) return 48;
  if (field.source === 'CUSTOM') return Math.min(68, Math.max(44, field.label.length * 10));
  return 44;
};
async function loadAccounts() { accounts.value = await getPromotionAccounts(); } async function loadFields() { fields.value = await getPromotionMetricFields(); }
function summary({ columns }: { columns: Array<{ label: string; property: string }> }) { const total = rows.value.reduce((result, row) => ({ spend: result.spend + Number(row.spend || 0), impressions: result.impressions + Number(row.impressions || 0), clicks: result.clicks + Number(row.clicks || 0), leads: result.leads + Number(row.leads || 0), validLeads: result.validLeads + Number(row.validLeads || 0), appointments: result.appointments + Number(row.appointments || 0), transactions: result.transactions + Number(row.transactions || 0), revenue: result.revenue + Number(row.revenue || 0) }), { spend: 0, impressions: 0, clicks: 0, leads: 0, validLeads: 0, appointments: 0, transactions: 0, revenue: 0 }); const calc = { clickRate: total.impressions ? total.clicks / total.impressions : null, validRate: total.leads ? total.validLeads / total.leads : null, averageCost: total.leads ? total.spend / total.leads : null, validCost: total.validLeads ? total.spend / total.validLeads : null, conversionRate: total.appointments ? total.transactions / total.appointments : null, arrivalRate: total.leads ? total.appointments / total.leads : null, validArrivalRate: total.validLeads ? total.appointments / total.validLeads : null, arrivalCost: total.appointments ? total.spend / total.appointments : null, roi: total.spend ? total.revenue / total.spend : null }; const labels: Record<string, string> = {}; fields.value.forEach((field) => { labels[field.label] = field.key; }); return columns.map((column, index) => { if (index === 0) return '合计'; if (index === 1) return ''; if (column.property === 'spend' || column.property === 'revenue') return money(total[column.property]); if (column.property && column.property in total) return String(total[column.property as keyof typeof total]); const key = labels[column.label]; if (!key) return ''; return key.includes('Rate') ? rate(calc[key as keyof typeof calc] as number | null) : number(calc[key as keyof typeof calc] as number | null); }); }
async function load() { loading.value = true; try { const [project, platform, accountName] = query.accountKey ? JSON.parse(query.accountKey) as string[] : ['', '', '']; sourceRows.value = await getPromotionDailyMetrics({ project, platform, accountName, dateFrom: dateRange.value?.[0] || '', dateTo: dateRange.value?.[1] || '' }); } finally { loading.value = false; } }
async function selectQuickRange(value: [string, string]) { dateRange.value = value; await load(); }
function openMetric(row?: PromotionDailyMetricItem) { Object.assign(metricForm, blankMetric(), row ? { ...row, remark: row.remark || '' } : {}); Object.keys(customValues).forEach((key) => delete customValues[key]); fields.value.filter((field) => field.source === 'CUSTOM').forEach((field) => { customValues[field.key] = row?.customMetrics?.[field.key] ?? (field.dataType === 'NUMBER' ? 0 : ''); }); metricVisible.value = true; }
async function saveMetric() { if (!metricForm.accountId) return ElMessage.warning('请选择推广账户'); saving.value = true; try { const { id: _id, ...data } = { ...metricForm, customMetrics: { ...customValues } }; if (metricForm.id) await updatePromotionDailyMetric(metricForm.id, data); else await createPromotionDailyMetric(data); ElMessage.success('已保存'); metricVisible.value = false; await load(); } finally { saving.value = false; } }
async function toggleArchive(row: PromotionDailyMetricItem) { const nextArchived = !row.isArchived; if (nextArchived) await ElMessageBox.confirm(`归档后“${row.account.name}”在 ${row.statDate} 的数据将不再被自动同步覆盖，确认归档吗？`, '归档确认', { type: 'warning' }); const updated = await archivePromotionDailyMetric(row.id, nextArchived); Object.assign(row, updated); ElMessage.success(updated.isArchived ? '已归档' : '已取消归档'); await load(); }
async function syncData() { syncing.value = true; try { const result = await syncPromotionDailyMetrics({ statDate: syncForm.statDate, ...(syncForm.provider ? { provider: syncForm.provider } : {}), ...(syncForm.accountIds.length ? { accountIds: syncForm.accountIds } : {}) }); const success = result.reduce((sum, item) => sum + item.synced, 0); const noData = result.reduce((sum, item) => sum + item.noData, 0); const errors = result.flatMap((item) => item.errors); const details = [`成功 ${success} 条`, ...(noData ? [`平台无数据 ${noData} 条`] : []), ...(errors.length ? [errors.join('；')] : [])]; ElMessage[errors.length || noData ? 'warning' : 'success'](`同步完成：${details.join('；')}`); syncVisible.value = false; await load(); } finally { syncing.value = false; } }
function openAccount(row?: PromotionAccountItem) { Object.assign(accountForm, { id: '', project: '重庆', platform: '', name: '', accountNo: '', status: 'ACTIVE', remark: '' }, row || {}); accountVisible.value = true; }
async function saveAccount() { if (!accountForm.platform.trim() || !accountForm.name.trim()) return ElMessage.warning('请填写渠道和账户名称'); const { id: _id, ...data } = accountForm; if (accountForm.id) await updatePromotionAccount(accountForm.id, data); else await createPromotionAccount(data); ElMessage.success('账户已保存'); accountVisible.value = false; await loadAccounts(); }
async function removeMetric(row: PromotionDailyMetricItem) { await ElMessageBox.confirm(`确认删除 ${row.statDate} 的日统计吗？`, '删除确认', { type: 'warning' }); await deletePromotionDailyMetric(row.id); ElMessage.success('已删除'); await load(); } async function removeAccount(row: PromotionAccountItem) { await ElMessageBox.confirm(`删除账户“${row.name}”会同时删除其全部日统计，确认继续吗？`, '删除确认', { type: 'warning' }); await deletePromotionAccount(row.id); ElMessage.success('已删除'); await loadAccounts(); await load(); }
onMounted(() => { void Promise.allSettled([loadAccounts(), loadFields(), load()]); });
</script>
<style scoped>
.detail-operation-actions {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  white-space: nowrap;
}
.detail-operation-actions :deep(.el-button) {
  flex: 0 0 auto;
  margin: 0;
  padding: 0;
}
</style>
<style scoped>
.detail-table{width:100%;font-size:12px;border-radius:10px;overflow:hidden}
.detail-table :deep(.el-table__cell){padding:4px 3px;text-align:center}
.detail-table :deep(.cell){white-space:normal;overflow-wrap:anywhere;word-break:break-word}
.detail-operation-actions{display:flex;justify-content:center;align-items:center;gap:4px;flex-wrap:nowrap;min-width:max-content}
.detail-operation-actions :deep(.el-button){margin:0;flex:none}
